# ── 쿠키 정규화 및 환경변수(YOUTUBE_COOKIES) 처리 ─────────────────────────────
def normalize_cookies_content(content):
    if not content:
        return ""
    if content.startswith('\ufeff'):
        content = content[1:]
    elif content.startswith('\xef\xbb\xbf'):
        content = content[3:]
    content = content.replace('\\n', '\n').replace('\r\n', '\n').strip()
    
    lines = []
    has_header = False
    for line in content.splitlines():
        line_str = line.strip()
        if not line_str:
            continue
        if line_str.startswith('#'):
            if 'Netscape HTTP Cookie File' in line_str:
                has_header = True
            lines.append(line_str)
            continue
        
        if '\t' in line:
            lines.append(line)
        else:
            parts = line_str.split(None, 6)
            if len(parts) == 7:
                lines.append('\t'.join(parts))
            elif len(parts) == 6:
                lines.append('\t'.join(parts) + '\t')
            else:
                lines.append(line)
                
    result = '\n'.join(lines) + '\n'
    if not has_header:
        result = "# Netscape HTTP Cookie File\n# http://curl.haxx.se/rfc/cookie_spec.html\n# This file was generated by yt-dlp! Edit at your own risk.\n\n" + result
    return result

def _write_cookies_from_env():
    cookies_env = os.environ.get('YOUTUBE_COOKIES', '')
    if not cookies_env:
        for cpath in ['cookies.txt', '/app/cookies.txt', '/etc/secrets/cookies.txt']:
            if os.path.exists(cpath):
                try:
                    with open(cpath, 'r', encoding='utf-8', errors='ignore') as f:
                        raw = f.read()
                    norm = normalize_cookies_content(raw)
                    with open(cpath, 'w', encoding='utf-8', newline='\n') as f:
                        f.write(norm)
                except: pass
        return
        
    cookies_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'cookies.txt')
    try:
        content = normalize_cookies_content(cookies_env)
        with open(cookies_path, 'w', encoding='utf-8', newline='\n') as f:
            f.write(content)
        if os.path.exists('/app'):
            try:
                with open('/app/cookies.txt', 'w', encoding='utf-8', newline='\n') as f:
                    f.write(content)
            except: pass
        print(f"[서버] YOUTUBE_COOKIES 환경변수에서 cookies.txt 정규화 생성 완료: {cookies_path}")
    except Exception as e:
        print(f"[서버] cookies.txt 생성 실패: {e}")

_write_cookies_from_env()
