@app.route('/api/auth/google', methods=['POST'])
def google_auth():
    token = request.json.get('token')
    if not token:
        return jsonify({"status": "fail", "message": "토큰이 없습니다."}), 400

    # 개발 편의를 위한 더미 토큰 우회 처리
    if token == "dummy-auth-token-for-testing":
        user_email = "test-user@example.com"
        user_name = "개발용테스터"
        session['user'] = user_email
        session['user_name'] = user_name

        # Supabase DB에 로그인 정보 기록
        if supabase_client:
            try:
                from datetime import datetime, timezone
                now_str = datetime.now(timezone.utc).isoformat()
                supabase_client.table("users").upsert({
                    "email": user_email,
                    "name": user_name,
                    "last_login_at": now_str
                }).execute()
            except Exception as db_err:
                print(f"[서버] 수파베이스 저장 실패: {str(db_err)}")

        return jsonify({
            "status": "success",
            "user": {
                "email": user_email,
                "name": user_name,
                "picture": ""
            }
        })

    try:
        from google.oauth2 import id_token
        from google.auth.transport import requests as google_requests

        id_info = id_token.verify_oauth2_token(token, google_requests.Request(), GOOGLE_CLIENT_ID)
        
        user_email = id_info.get('email')
        user_name = id_info.get('name')
        user_picture = id_info.get('picture')

        session['user'] = user_email
        session['user_name'] = user_name

        # Supabase DB에 로그인 정보 기록
        if supabase_client:
            try:
                from datetime import datetime, timezone
                now_str = datetime.now(timezone.utc).isoformat()
                supabase_client.table("users").upsert({
                    "email": user_email,
                    "name": user_name,
                    "last_login_at": now_str
                }).execute()
            except Exception as db_err:
                print(f"[서버] 수파베이스 저장 실패: {str(db_err)}")

        return jsonify({
            "status": "success",
            "user": {
                "email": user_email,
                "name": user_name,
                "picture": user_picture
            }
        })
    except Exception as e:
        return jsonify({"status": "fail", "message": f"구글 토큰 검증 실패: {str(e)}"}), 401

