@app.route('/api/proxy/google/youtube/<path:subpath>', methods=['GET', 'POST'])
def proxy_youtube(subpath):
    # Construct the target YouTube API URL
    args = dict(request.args)
    server_yt_key = os.environ.get('YOUTUBE_API_KEY', '').strip()
    current_key = str(args.get('key', '')).strip()
    if (not current_key or current_key in ['undefined', 'null', 'SERVER_DEFAULT', 'default_server_key', 'none']) and server_yt_key:
        args['key'] = server_yt_key
    from urllib.parse import urlencode
    qs = urlencode(args)
    target_url = f"https://www.googleapis.com/youtube/{subpath}"
    if qs:
        target_url += f"?{qs}"
    return handle_google_request(target_url)

@app.route('/api/proxy/google/gemini/<path:subpath>', methods=['GET', 'POST'])
def proxy_gemini(subpath):
    # Construct the target Gemini API URL
    args = dict(request.args)
    server_gem_key = os.environ.get('GEMINI_API_KEY', '').strip()
    current_key = str(args.get('key', '')).strip()
    if (not current_key or current_key in ['undefined', 'null', 'SERVER_DEFAULT', 'default_server_key', 'none']) and server_gem_key:
        args['key'] = server_gem_key
    from urllib.parse import urlencode
    qs = urlencode(args)
    target_url = f"https://generativelanguage.googleapis.com/{subpath}"
    if qs:
        target_url += f"?{qs}"
    return handle_google_request(target_url)

def handle_google_request(url):
    try:
        method = request.method
        data = request.get_data() if method == 'POST' else None
        
        # Build headers
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        }
        for k, v in request.headers.items():
            if k.lower() not in ['host', 'origin', 'referer', 'content-length', 'user-agent', 'accept-encoding']:
                headers[k] = v
        
        # Use requests library for more robust handling
        # Verify=False to avoid SSL issues in some environments (similar to unverified context)
        resp = requests.request(
            method=method,
            url=url,
            data=data,
            headers=headers,
            timeout=45,
            verify=False
        )
        
        # Build response headers to return to browser
        excluded_headers = ['content-encoding', 'content-length', 'transfer-encoding', 'connection']
        resp_headers = [(name, value) for (name, value) in resp.raw.headers.items()
                        if name.lower() not in excluded_headers]
        
        return (resp.content, resp.status_code, resp_headers)
            
    except Exception as e:
        error_msg = str(e)
        print(f"[Google Request Error] {url}: {error_msg}")
        import traceback
        traceback.print_exc()
        return jsonify({
            "error": {
                "code": 500,
                "message": f"Server Proxy Error: {error_msg}",
                "status": "INTERNAL"
            }
        }), 500

@app.route('/api/proxy/google', methods=['GET', 'POST'])
def proxy_google():
    # Keep legacy proxy for any other googleapis.com calls
    try:
        raw_url = request.url
        if 'url=' in raw_url:
            url = raw_url.split('url=', 1)[1]
            import urllib.parse
            url = urllib.parse.unquote(url)
            return handle_google_request(url)
        return jsonify({"success": False, "error": "URL parameter missing"}), 400
    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/cobalt', methods=['POST'])
def cobalt_proxy():
    """Invidious API를 통해 YouTube 스트림 URL 추출 (cobalt.tools 대체)"""
    try:
        body = request.get_json()
        if not body or not body.get('url'):
            return jsonify({"success": False, "error": "url missing"}), 400

        target_url = body.get('url', '')
        audio_only = body.get('downloadMode') == 'audio'

        # YouTube video ID 추출
        import re
        yt_id_match = re.search(
            r'(?:youtube\.com/(?:watch\?v=|shorts/)|youtu\.be/)([A-Za-z0-9_-]{11})',
            target_url
        )
        if not yt_id_match:
            # TikTok 등 YouTube가 아닌 URL은 fallback
            return jsonify({
                "status": "fallback",
                "fallback_url": f"https://cobalt.tools/#{target_url}",
                "error": "YouTube URL이 아닙니다."
            }), 200

        video_id = yt_id_match.group(1)
        print(f"[cobalt_proxy] video_id={video_id}, audio_only={audio_only}")
        last_err = None

        # 1순위: yt-dlp 로컬 엔진 시도 (매우 안정적)
        try:
            import yt_dlp
            print("[cobalt_proxy] yt-dlp를 통한 직접 추출 시도...")
            ydl_opts = {
                'quiet': True,
                'skip_download': True,
                'format': 'bestaudio/best' if audio_only else 'best[ext=mp4]/best'
            }
            with yt_dlp.YoutubeDL(ydl_opts) as ydl:
                info = ydl.extract_info(target_url, download=False)
                stream_url = info.get('url')
                title = info.get('title', video_id)
                
                if stream_url:
                    ext = 'mp3' if audio_only else 'mp4'
                    filename = f"{title}.{ext}"
                    # 파일명 안전하게 변환
                    import re
                    filename = re.sub(r'[\\/*?:"<>|]', "", filename)
                    
                    print(f"[cobalt_proxy] yt-dlp 추출 성공: {filename}")
                    return jsonify({
                        "status": "redirect",
                        "url": stream_url,
                        "filename": filename,
                    })
        except Exception as e:
            last_err = f"yt-dlp 에러: {str(e)}"
            print(f"[cobalt_proxy] {last_err}")

        # 2순위: Invidious 공개 인스턴스 목록 (순서대로 시도)
        INVIDIOUS_INSTANCES = [
            'https://inv.nadeko.net',
            'https://invidious.nerdvpn.de',
            'https://invidious.flokinet.to',
            'https://y.com.sb',
            'https://vid.puffyan.us',
            'https://invidious.tiekoetter.com',
        ]

        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'Accept': 'application/json',
        }

        for instance in INVIDIOUS_INSTANCES:
            try:
                api_url = f"{instance}/api/v1/videos/{video_id}?fields=title,formatStreams,adaptiveFormats"
                resp = requests.get(api_url, headers=headers, timeout=12, verify=False)
                if resp.status_code != 200:
                    print(f"[invidious] {instance} HTTP {resp.status_code}")
                    continue

                data = resp.json()
                if 'error' in data:
                    print(f"[invidious] {instance} 에러: {data['error']}")
                    continue

                title = data.get('title', video_id)
                fmt_streams = data.get('formatStreams', [])   # 비디오+오디오 합본
                adaptive = data.get('adaptiveFormats', [])   # 비디오/오디오 분리

                if audio_only:
                    # 오디오 스트림 선택 (m4a > webm 순)
                    audio_fmts = [f for f in adaptive if f.get('type', '').startswith('audio')]
                    audio_fmts.sort(key=lambda f: int(f.get('bitrate', 0)), reverse=True)
                    if not audio_fmts:
                        last_err = f"{instance}: 오디오 포맷 없음"
                        continue
                    chosen = audio_fmts[0]
                    ext = 'mp3' if 'mp4' in chosen.get('type','') else 'webm'
                    filename = f"{title}.{ext}"
                else:
                    # 비디오+오디오 합본 선택 (720p > 360p)
                    if fmt_streams:
                        fmt_streams.sort(
                            key=lambda f: int(f.get('resolution', '0p').replace('p', '') or 0),
                            reverse=True
                        )
                        chosen = fmt_streams[0]
                    else:
                        # 합본 없으면 최고 품질 adaptive 비디오
                        video_fmts = [f for f in adaptive if f.get('type', '').startswith('video')]
                        video_fmts.sort(
                            key=lambda f: int(f.get('resolution', '0p').replace('p', '') or 0),
                            reverse=True
                        )
                        if not video_fmts:
                            last_err = f"{instance}: 비디오 포맷 없음"
                            continue
                        chosen = video_fmts[0]
                    filename = f"{title}.mp4"

                stream_url = chosen.get('url', '')
                if not stream_url:
                    last_err = f"{instance}: URL 없음"
                    continue

                # 파일명 안전하게 변환
                import re
                filename = re.sub(r'[\\/*?:"<>|]', "", filename)
                
                print(f"[invidious] {instance} 성공: {filename}")
                return jsonify({
                    "status": "redirect",
                    "url": stream_url,
                    "filename": filename,
                })

            except Exception as e:
                last_err = str(e)
                print(f"[invidious] {instance} 예외: {e}")
                continue

        # 모든 인스턴스 실패 → fallback (새 탭으로 외부 서비스 열기)
        fallback = f"https://ssyoutube.com/watch?v={video_id}"
        return jsonify({
            "status": "fallback",
            "fallback_url": fallback,
            "error": last_err or "모든 Invidious 인스턴스 실패"
        }), 200

    except Exception as e:
        return jsonify({"success": False, "error": str(e)}), 500

# --- YouTube API Usage Tracking ---
def get_usage_file_path():
    appdata = os.environ.get('APPDATA') or os.path.expanduser('~')
    dir_path = os.path.join(appdata, 'YouTubeDiscoveryTool')
    if not os.path.exists(dir_path): os.makedirs(dir_path)
    return os.path.join(dir_path, 'youtube_usage.json')

USAGE_FILE = get_usage_file_path()

def load_usage():
    today = time.strftime('%Y-%m-%d')
    default_usage = {"date": today, "used_units": 0, "daily_limit": 10000}
    if os.path.exists(USAGE_FILE):
        try:
            with open(USAGE_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
                if data.get('date') == today: return data
        except: pass
    return default_usage

def save_usage(usage):
    try:
        with open(USAGE_FILE, 'w', encoding='utf-8') as f: json.dump(usage, f)
    except: pass

@app.route('/api/usage/record', methods=['POST'])
def record_usage():
    try:
        data = request.json
        units = data.get('units', 0)
        usage = load_usage()
        usage['used_units'] += units
        save_usage(usage)
        return jsonify({"success": True, "usage": usage})
    except Exception as e: return jsonify({"success": False, "error": str(e)}), 500

@app.route('/api/usage/stats', methods=['GET'])
def get_usage_stats():
    try:
        usage = load_usage()
        return jsonify({"success": True, "usage": usage})
    except Exception as e: return jsonify({"success": False, "error": str(e)}), 500
