def get_db_connection():
    db_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'analytics.db')
    conn = sqlite3.connect(db_path, timeout=30.0, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn

