@app.route('/api/track/login', methods=['POST'])
def track_login():
    data = request.json
    email = data.get('email')
    name = data.get('name', '')
    if not email:
        return jsonify({'status': 'fail'}), 400
    
    conn = get_db_connection()
    c = conn.cursor()
    now = datetime.now().isoformat()
    
    c.execute('SELECT * FROM users WHERE email = ?', (email,))
    user = c.fetchone()
    if user:
        c.execute('UPDATE users SET login_count = login_count + 1, last_login = ? WHERE email = ?', (now, email))
    else:
        c.execute('INSERT INTO users (email, name, login_count, total_time_seconds, last_login) VALUES (?, ?, 1, 0, ?)', (email, name, now))
    
    conn.commit()
    conn.close()
    return jsonify({'status': 'success'})

@app.route('/api/track/pageview', methods=['POST'])
def track_pageview():
    data = request.json
    email = data.get('email', 'anonymous')
    page_name = data.get('page_name')
    if not page_name:
        return jsonify({'status': 'fail'}), 400
        
    conn = get_db_connection()
    c = conn.cursor()
    c.execute('INSERT INTO page_views (email, page_name, timestamp) VALUES (?, ?, ?)', (email, page_name, datetime.now().isoformat()))
    conn.commit()
    conn.close()
    return jsonify({'status': 'success'})

@app.route('/api/track/session', methods=['POST'])
def track_session():
    data = request.json
    email = data.get('email')
    time_spent = data.get('time_spent', 0)  # in seconds
    if not email or time_spent <= 0:
        return jsonify({'status': 'fail'}), 400
        
    conn = get_db_connection()
    c = conn.cursor()
    c.execute('UPDATE users SET total_time_seconds = total_time_seconds + ? WHERE email = ?', (time_spent, email))
    conn.commit()
    conn.close()
    return jsonify({'status': 'success'})

# ------------------ ADMIN APIs ------------------
import jwt
from functools import wraps

def admin_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header or not auth_header.startswith('Bearer '):
            return jsonify({'status': 'fail', 'message': 'Missing token'}), 401
        
        token = auth_header.split(' ')[1]
        try:
            payload = jwt.decode(token, options={'verify_signature': False})
            email = payload.get('email')
            if email != 'imomsschool@gmail.com':
                return jsonify({'status': 'fail', 'message': 'Unauthorized email'}), 403
        except Exception as e:
            return jsonify({'status': 'fail', 'message': 'Invalid token'}), 401
            
        return f(*args, **kwargs)
    return decorated_function

@app.route('/api/admin/upload-cookie', methods=['POST'])
@admin_required
def admin_upload_cookie():
    if 'file' not in request.files:
        return jsonify({'status': 'fail', 'message': 'No file part'}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({'status': 'fail', 'message': 'No selected file'}), 400
    if file:
        try:
            import os
            # Save to root directory where youtube_extractor.py looks for it
            save_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'cookies.txt')
            file.save(save_path)
            return jsonify({'status': 'success', 'message': 'Cookies updated successfully'})
        except Exception as e:
            return jsonify({'status': 'fail', 'message': str(e)}), 500

@app.route('/api/admin/clear-cache', methods=['POST'])
@admin_required
def admin_clear_cache():
    try:
        # Clear yt-dlp cache by executing command
        import subprocess
        subprocess.run(['yt-dlp', '--rm-cache-dir'], capture_output=True)
        return jsonify({'status': 'success', 'message': 'Cache cleared successfully'})
    except Exception as e:
        return jsonify({'status': 'fail', 'message': str(e)}), 500

@app.route('/api/admin/analytics', methods=['GET'])
@admin_required
def get_analytics():
    conn = get_db_connection()
    c = conn.cursor()
    
    # 1. Top Menus
    c.execute('''SELECT page_name, COUNT(*) as views 
                 FROM page_views 
                 GROUP BY page_name 
                 ORDER BY views DESC LIMIT 10''')
    top_menus = [dict(row) for row in c.fetchall()]
    
    # 2. User Rankings (Top by login count or time spent)
    c.execute('''SELECT email, name, login_count, total_time_seconds, last_login 
                 FROM users 
                 ORDER BY login_count DESC, total_time_seconds DESC LIMIT 50''')
    user_rankings = [dict(row) for row in c.fetchall()]
    
    # 3. Overall Stats
    c.execute('SELECT COUNT(*) FROM users')
    total_users = c.fetchone()[0]
    
    c.execute('SELECT COUNT(*) FROM page_views')
    total_page_views = c.fetchone()[0]
    
    conn.close()
    
    return jsonify({
        'status': 'success',
        'data': {
            'top_menus': top_menus,
            'user_rankings': user_rankings,
            'stats': {
                'total_users': total_users,
                'total_page_views': total_page_views
            }
        }
    })
